using System.Text.Json.Serialization;
using Square.Core.Models;

namespace Square.Models;

/// <summary>
/// Request object for the <see href="https://developer.squareup.com/reference/square_2024-05-15/merchants-api/list-merchants">ListMerchant</see> endpoint.
/// </summary>
public record ListMerchantsRequest
{
    /// <summary>
    /// The cursor generated by the previous response.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
